add_filter( 'the_content', 'perfectpixel_last_updated_date', 6 );

function perfectpixel_last_updated_date( $content ) {
	if ( ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() ) {
		return $content;
	}
	if ( (int) get_the_modified_time( 'U' ) - (int) get_the_time( 'U' ) < DAY_IN_SECONDS ) {
		return $content;
	}
	return '<p class="perfectpixel-last-updated">' . esc_html( '{{last_updated_label}}' ) . ' <time datetime="' . esc_attr( get_the_modified_date( 'c' ) ) . '">' . esc_html( get_the_modified_date() ) . '</time></p>' . $content;
}
